<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake — 30x30</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: radial-gradient(ellipse at center, #14142a 0%, #06060d 100%);
    color: #e6e6f0;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
  }
  .wrap { display: flex; flex-direction: column; align-items: center; gap: 16px; }
  h1 {
    font-size: 48px;
    letter-spacing: 8px;
    background: linear-gradient(90deg, #4ade80, #38bdf8, #c084fc);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    text-shadow: 0 0 30px rgba(120,200,255,0.3);
    margin-bottom: 8px;
  }
  h2 { font-size: 32px; margin-bottom: 12px; }
  .panel {
    background: rgba(20,20,40,0.7);
    border: 1px solid #2a2a4a;
    border-radius: 12px;
    padding: 24px 32px;
    backdrop-filter: blur(10px);
    box-shadow: 0 8px 32px rgba(0,0,0,0.5);
    min-width: 380px;
  }
  .menu p { margin: 8px 0; }
  .menu .hint { color: #8888aa; font-size: 14px; margin-top: 16px; }
  .mode-list { display: flex; flex-direction: column; gap: 10px; margin: 16px 0; }
  .mode-list button {
    background: linear-gradient(90deg, #1e1e3a, #2a2a4a);
    border: 1px solid #3a3a5a;
    color: #e6e6f0;
