    cursor: pointer;
    transition: all 0.15s;
    text-align: left;
    font-family: inherit;
  }
  .mode-list button:hover, .mode-list button:focus {
    border-color: #6a6aaa;
    background: linear-gradient(90deg, #2a2a4a, #3a3a5a);
    outline: none;
    transform: translateX(4px);
  }
  .mode-list button .key {
    display: inline-block;
